precision highp float;
varying vec2 v_texCoord;
uniform float u_time;
uniform float u_dispersion;
uniform float u_bevelDepth;
uniform vec2 u_resolution;

float sdSquircle(vec2 p, vec2 size, float n) {
    vec2 d = abs(p) / size;
    float dist = pow(pow(d.x, n) + pow(d.y, n), 1.0 / n);
    return (dist - 1.0) * min(size.x, size.y);
}

vec3 getBackground(vec2 uv) {
    float t = u_time * 0.4;
    vec3 col = vec3(0.02, 0.04, 0.06);
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        vec2 center = vec2(0.3 + fi * 0.15, 0.5 + 0.3 * sin(t + fi));
        float d = length(uv - center);
        vec3 c = vec3(0.1 + fi * 0.1, 0.4 + fi * 0.1, 0.6 - fi * 0.05);
        col += c * 0.35 * smoothstep(0.35, 0.0, d);
    }
    return col;
}

void main() {
    vec2 uv = v_texCoord;
    vec2 panelSize = vec2(320.0, 220.0);
    vec2 panelUV = (uv - 0.5) * u_resolution / vec2(700.0, 380.0) * vec2(1.4, 1.3) + 0.5;
    vec2 p = (panelUV - 0.5) * panelSize;

    float d = sdSquircle(p, panelSize * 0.5, 4.0);
    float mask = 1.0 - smoothstep(-1.5, 1.5, d);

    vec3 bg = getBackground(uv);

    if (mask < 0.001) {
        gl_FragColor = vec4(bg, 1.0);
        return;
    }

    // Bevel geometry
    float radius = 35.0;
    float edgeDist = -d;
    float effectZone = radius * 1.5;
    float edgeFactor = 1.0 - smoothstep(0.0, effectZone, edgeDist);
    float zonePos = clamp(1.0 - edgeDist / effectZone, 0.0, 1.0);
    float bevelAmount = (1.0 - sqrt(1.0 - zonePos * zonePos * u_bevelDepth)) * edgeFactor;

    // Gradient direction
    float eps = 3.0;
    float dx = sdSquircle(p + vec2(eps, 0.0), panelSize * 0.5, 4.0) - sdSquircle(p - vec2(eps, 0.0), panelSize * 0.5, 4.0);
    float dy = sdSquircle(p + vec2(0.0, eps), panelSize * 0.5, 4.0) - sdSquircle(p - vec2(0.0, eps), panelSize * 0.5, 4.0);
    vec2 gradDir = normalize(vec2(dx, dy) / panelSize + 0.001);

    // Refraction with chromatic aberration
    vec2 refract = gradDir * bevelAmount * 0.15;

    float dispR = mix(1.0, 0.85, u_dispersion);
    float dispG = 1.0;
    float dispB = mix(1.0, 1.2, u_dispersion);

    vec3 glassColor;
    glassColor.r = getBackground(uv + refract * dispR).r;
    glassColor.g = getBackground(uv + refract * dispG).g;
    glassColor.b = getBackground(uv + refract * dispB).b;

    // Fake blur
    for (int i = 0; i < 4; i++) {
        float angle = float(i) * 1.57;
        vec2 off = vec2(cos(angle), sin(angle)) * 0.015;
        glassColor.r += getBackground(uv + refract * dispR + off).r * 0.15;
        glassColor.g += getBackground(uv + refract * dispG + off).g * 0.15;
        glassColor.b += getBackground(uv + refract * dispB + off).b * 0.15;
    }
    glassColor /= 1.6;

    // Tint
    glassColor *= vec3(0.95, 0.97, 1.0);

    // Edge highlight
    float edgeGlow = smoothstep(10.0, 0.0, abs(d)) * 0.2;
    glassColor += vec3(1.0) * edgeGlow;

    vec3 finalColor = mix(bg, glassColor, mask);
    gl_FragColor = vec4(finalColor, 1.0);
}

