sections.fragmentShader:
precision highp float;
varying vec2 v_texCoord;
uniform float u_time;
uniform float u_caustics;
uniform float u_specular;
uniform float u_chromatic;
uniform vec2 u_resolution;

float sdSquircle(vec2 p, vec2 size, float n) {
    vec2 d = abs(p) / size;
    float dist = pow(pow(d.x, n) + pow(d.y, n), 1.0 / n);
    return (dist - 1.0) * min(size.x, size.y);
}

vec3 getBackground(vec2 uv) {
    vec3 col = vec3(0.015, 0.025, 0.04);
    float t = u_time * 0.2;
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        vec2 center = vec2(0.25 + fi * 0.2, 0.5 + 0.25 * sin(t * 0.7 + fi * 1.2));
        float d = length(uv - center);
        col += vec3(0.15, 0.35, 0.5) * 0.4 * smoothstep(0.4, 0.0, d);
    }
    return col;
}

void main() {
    vec2 uv = v_texCoord;
    vec2 panelSize = vec2(300.0, 200.0);
    vec2 panelUV = (uv - 0.5) * u_resolution / vec2(700.0, 400.0) * vec2(1.5, 1.4) + 0.5;
    vec2 p = (panelUV - 0.5) * panelSize;

    float d = sdSquircle(p, panelSize * 0.5, 4.0);
    float mask = 1.0 - smoothstep(-1.5, 1.5, d);

    vec3 bg = getBackground(uv);

    if (mask < 0.001) {
        gl_FragColor = vec4(bg, 1.0);
        return;
    }

    // Bevel geometry
    float radius = 40.0;
    float edgeDist = -d;
    float effectZone = radius * 1.8;
    float edgeFactor = 1.0 - smoothstep(0.0, effectZone, edgeDist);
    float zonePos = clamp(1.0 - edgeDist / effectZone, 0.0, 1.0);
    float bevelAmount = (1.0 - sqrt(1.0 - zonePos * zonePos * 0.8)) * edgeFactor;

    // Gradient
    float eps = 3.0;
    float dx = sdSquircle(p + vec2(eps, 0.0), panelSize * 0.5, 4.0) - sdSquircle(p - vec2(eps, 0.0), panelSize * 0.5, 4.0);
    float dy = sdSquircle(p + vec2(0.0, eps), panelSize * 0.5, 4.0) - sdSquircle(p - vec2(0.0, eps), panelSize * 0.5, 4.0);
    vec2 gradDir = normalize(vec2(dx, dy) + 0.001);

    // Base glass color with refraction
    vec2 refract = gradDir * bevelAmount * 0.12;
    vec3 glassColor = getBackground(uv + refract) * 0.9;
    glassColor *= vec3(0.92, 0.96, 1.0);

    // Animated light position
    float lt = u_time * 0.5;
    vec3 lightPos = vec3(0.7 + 0.3 * sin(lt), 0.3 + 0.2 * cos(lt * 0.7), 0.5);
    vec3 lightColor = vec3(1.0, 0.95, 0.85);

    // Specular with chromatic aberration
    vec3 normal = normalize(vec3(-gradDir * bevelAmount * 2.0, 1.0));
    vec3 viewDir = vec3(0.0, 0.0, 1.0);
    vec3 lightDir = normalize(lightPos - vec3(panelUV, 0.0));
    vec3 halfVec = normalize(lightDir + viewDir);
    float NdotH = max(dot(normal, halfVec), 0.0);

    float F0_R = 0.04 * mix(1.0, 0.94, u_chromatic);
    float F0_G = 0.04;
    float F0_B = 0.04 * mix(1.0, 1.08, u_chromatic);

    float fresnel_R = F0_R + (1.0 - F0_R) * pow(1.0 - NdotH, 5.0);
    float fresnel_G = F0_G + (1.0 - F0_G) * pow(1.0 - NdotH, 5.0);
    float fresnel_B = F0_B + (1.0 - F0_B) * pow(1.0 - NdotH, 5.0);

    float specPower = pow(NdotH, 64.0);
    vec3 specular = lightColor * vec3(fresnel_R, fresnel_G, fresnel_B) * specPower * u_specular * 3.0;

    // Caustics with chromatic aberration
    float edgeR = edgeFactor * mix(1.0, 0.7, u_chromatic);
    float edgeG = edgeFactor;
    float edgeB = edgeFactor * mix(1.0, 1.4, u_chromatic);

    float bandR = pow(clamp(edgeR, 0.0, 1.0) * (1.0 - edgeR * 0.5), 0.4);
    float bandG = pow(clamp(edgeG, 0.0, 1.0) * (1.0 - edgeG * 0.5), 0.4);
    float bandB = pow(clamp(edgeB, 0.0, 1.0) * (1.0 - edgeB * 0.5), 0.4);

    float focusingPower = bevelAmount * bevelAmount * 12.0;
    float lightAlign = abs(dot(normalize(lightPos.xy - panelUV), gradDir));
    float baseStrength = focusingPower * lightAlign;

    vec3 caustics = lightColor * vec3(bandR, bandG, bandB) * baseStrength * u_caustics;

    glassColor += specular + caustics;

    // Edge glow
    float edgeGlow = smoothstep(12.0, 0.0, abs(d)) * 0.12;
    glassColor += vec3(1.0) * edgeGlow;

    vec3 finalColor = mix(bg, glassColor, mask);
    gl_FragColor = vec4(finalColor, 1.0);
}
